DELIMITER $$
CREATE TRIGGER `insert_queue_from_order` AFTER INSERT ON `order_table` FOR EACH ROW BEGIN
  DECLARE newQueueIndex INT DEFAULT 1;

  IF NEW.CancelFlag = 0 THEN
    -- Step 1: Get highest active QueueIndex for this RateCard
    SELECT IFNULL(MAX(QueueIndex), 0) + 1 INTO newQueueIndex
    FROM queue_table
    WHERE RateCard = NEW.Card
      AND DATE(EntryDateTime) = CURDATE()
      AND Status NOT IN ('Completed', 'Deleted');

    -- Step 2: Insert the new queue entry using the variable
        QueueIndex, EntryDateTime, ClientName, ClientContact,
        RateCard, RateType, Status, Remarks, QueueInTime
    )
    VALUES (
        newQueueIndex,
        NOW(),
        NEW.ClientName,
        NEW.ClientContact,
        NEW.Card,
        NEW.AdType,
        'Waiting',
        '',
        NOW()
    );
  END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_before_insert_order` BEFORE INSERT ON `order_table` FOR EACH ROW BEGIN
    IF NEW.RateWiseOrderNumber = 0 THEN
        SET NEW.RateWiseOrderNumber = NEW.OrderNumber;
    END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `update_queue_from_order` AFTER UPDATE ON `order_table` FOR EACH ROW BEGIN
  -- Case: Order is updated (not cancelled), and relevant fields changed
  IF NEW.CancelFlag <> 1 AND (
      NEW.ClientName <> OLD.ClientName OR
      NEW.ClientContact <> OLD.ClientContact OR
      NEW.Card <> OLD.Card OR
      NEW.AdType <> OLD.AdType
  ) THEN
    UPDATE queue_table
    SET
      ClientName = NEW.ClientName,
      ClientContact = NEW.ClientContact,
      RateCard = NEW.Card,
      RateType = NEW.AdType
    WHERE ClientName = OLD.ClientName  
      AND ClientContact = OLD.ClientContact
      AND RateCard = OLD.Card
      AND RateType = OLD.AdType;
  END IF;
END
$$
DELIMITER ;

